"""Freestanding GBA variants; pristine MIT upstream sources are in vendor/."""
from pathlib import Path
import re,struct
P=Path(__file__).resolve().parent
s=(P/'vendor/z80/z80.c').read_text()
s=re.sub(r'void z80_debug_output\(.*?\n}\n','void z80_debug_output(z80* const z) {(void)z;}\n',s,flags=re.S)
s=re.sub(r'fprintf\(stderr,.*?\);','(void)0;',s)
# PSC8 owns the only Z80 instance on GBA. Replace generic function-pointer bus
# callbacks with direct hot-section calls; this removes multiple indirect ARM
# branches from every opcode fetch/data access while retaining the pristine
# upstream core in vendor/.
s=s.replace('#include "z80.h"', '#include "z80.h"\nextern uint8_t psc8_z80_read(uint16_t);\nextern void psc8_z80_write(uint16_t,uint8_t);\nextern uint8_t psc8_z80_in(z80*,uint8_t);\nextern void psc8_z80_out(z80*,uint8_t,uint8_t);')
s=re.sub(r'static inline uint8_t rb\(z80\* const z, uint16_t addr\) \{.*?\n\}', 'static inline uint8_t rb(z80* const z, uint16_t addr) {(void)z; return psc8_z80_read(addr);}', s, count=1, flags=re.S)
s=re.sub(r'static inline void wb\(z80\* const z, uint16_t addr, uint8_t val\) \{.*?\n\}', 'static inline void wb(z80* const z, uint16_t addr, uint8_t val) {(void)z; psc8_z80_write(addr,val);}', s, count=1, flags=re.S)
s=re.sub(r'static inline uint16_t rw\(z80\* const z, uint16_t addr\) \{.*?\n\}', 'static inline uint16_t rw(z80* const z, uint16_t addr) {(void)z; return ((uint16_t)psc8_z80_read(addr+1)<<8)|psc8_z80_read(addr);}', s, count=1, flags=re.S)
s=re.sub(r'static inline void ww\(z80\* const z, uint16_t addr, uint16_t val\) \{.*?\n\}', 'static inline void ww(z80* const z, uint16_t addr, uint16_t val) {(void)z; psc8_z80_write(addr,(uint8_t)val); psc8_z80_write(addr+1,(uint8_t)(val>>8));}', s, count=1, flags=re.S)
s=s.replace('z->port_in(z,', 'psc8_z80_in(z,').replace('z->port_out(z,', 'psc8_z80_out(z,')
# Upstream parity loops over all 8 bits on every flag-setting logic/arithmetic
# operation. Use the standard folded-nibble parity identity instead.
s=re.sub(r'static inline bool parity\(uint8_t val\) \{.*?\n\}', 'static inline bool parity(uint8_t val) {val ^= val >> 4; val &= 15; return (0x9669u >> val) & 1u;}', s, count=1, flags=re.S)
# Batch instruction stepping inside the hot core so the outer scheduler does
# not pay a function call/return for every emulated instruction.
step_pat=r'void z80_step\(z80\* const z\) \{.*?\n\}'
m=re.search(step_pat,s,flags=re.S); assert m
run='#include "z80_fast_spans.inc"\n#ifdef PSC8_PROFILE\nuint16_t z80_pc_profile[65536];\n#define PROFILE_PC(_z) do { z80_pc_profile[(_z)->pc]++; } while(0)\n#else\n#define PROFILE_PC(_z) do {} while(0)\n#endif\nvoid z80_step(z80* const z) {\n  PROFILE_PC(z);\n  if (z->halted) exec_opcode(z, 0x00); else {const uint8_t opcode=nextb(z); exec_opcode(z, opcode);}\n  process_interrupts(z);\n}\nvoid z80_run_until(z80* const z, uint32_t target) {\n  (void)z80_fast_span(z,target);\n  while(z->cyc < target) {\n    PROFILE_PC(z);\n    if (z->halted) exec_opcode(z, 0x00); else {const uint8_t opcode=nextb(z); exec_opcode(z, opcode);}\n    process_interrupts(z);\n  }\n}\n#undef PROFILE_PC'
s=s[:m.start()]+run+s[m.end():]
(P/'z80_gba.c').write_text(s)
h=(P/'vendor/z80/z80.h').read_text().replace('#include <stdio.h>','#include <stddef.h>')
h=h.replace('void z80_step(z80* const z);','void z80_step(z80* const z);\nvoid z80_run_until(z80* const z, uint32_t target);')
(P/'include/z80.h').write_text(h)
s=(P/'vendor/emu2413/emu2413.c').read_text()
for h in ['math.h','stdio.h','stdlib.h']:s=s.replace('#include <'+h+'>','')
# Constant tables generated by unmodified upstream initializeTables on the host.
for name,typ,dims,file in [('fullsin_table','uint16_t','[PG_WIDTH]','sin'),('halfsin_table','uint16_t','[PG_WIDTH]','half'),('tll_table','uint32_t','[128][64][4]','tll'),('rks_table','int32_t','[16][2]','rks'),('default_patch','OPLL_PATCH','[3][38]','patch')]:
 data=(P/'tables'/('opll_'+file+'.bin')).read_bytes();fmt={'uint16_t':'H','uint32_t':'I','int32_t':'i','OPLL_PATCH':'I'}[typ];vals=struct.unpack('<'+fmt*(len(data)//struct.calcsize(fmt)),data)
 if name=='tll_table':
  assert max(vals)<=255;typ='uint8_t'
 decl='static '+('' if name=='default_patch' else 'const ')+typ+' '+name+dims+' = {\n'+','.join(map(str,vals))+'\n};'
 pattern=r'static '+('uint32_t' if name=='tll_table' else typ)+r' '+name+r'\[.*?;'
 s,n=re.subn(pattern,lambda m:decl,s,count=1,flags=re.S);assert n==1,name
s=s.replace('static uint16_t *wave_table_map','static const uint16_t *wave_table_map')
s=re.sub(r'static double kl_table\[16\].*?;', '',s,flags=re.S)
s=re.sub(r'/\* Note: to disable internal rate converter.*?static uint8_t table_initialized = 0;','static uint8_t table_initialized = 1;',s,flags=re.S)
s=re.sub(r'static void initializeTables\(void\).*?\n}', 'static void initializeTables(void) {}',s,flags=re.S)
s=s.replace('opll = (OPLL *)calloc(1, sizeof(OPLL));','static OPLL storage; opll = &storage; memset(opll, 0, sizeof(*opll));')
s=re.sub(r'void OPLL_delete\(OPLL \*opll\).*?\n}', 'void OPLL_delete(OPLL *opll) {(void)opll;}',s,flags=re.S)
s=re.sub(r'static void reset_rate_conversion_params\(OPLL \*opll\).*?\n}', 'static void reset_rate_conversion_params(OPLL *opll) {opll->out_time = 0; opll->conv = 0;}',s,flags=re.S)
s=re.sub(r'INLINE static void mix_output\(OPLL \*opll\).*?\n}', 'INLINE static void mix_output(OPLL *opll) {int out=0; for(int i=0;i<14;i++) out+=opll->ch_out[i]; opll->mix_out[0]=out;}',s,flags=re.S)
s=re.sub(r'INLINE static void mix_output_stereo\(OPLL \*opll\).*?\n}', '',s,flags=re.S)
s=re.sub(r'int16_t OPLL_calc\(OPLL \*opll\).*?\n}', '''int16_t OPLL_calc(OPLL *opll) {
  /* Exact clock/72 phase; integer box filter replaces floating sinc conversion. */
  int sum=0, n=0; opll->out_time += opll->clk;
  while(opll->out_time >= opll->rate*72u) {opll->out_time -= opll->rate*72u; update_output(opll); mix_output(opll); sum+=opll->mix_out[0]; n++;}
  return n==3 ? sum/3 : n==2 ? sum/2 : sum;
}''',s,flags=re.S)
s=re.sub(r'void OPLL_calcStereo\(OPLL \*opll, int32_t out\[2\]\).*?\n}', 'void OPLL_calcStereo(OPLL *opll,int32_t out[2]) {out[0]=out[1]=OPLL_calc(opll);}',s,flags=re.S)
# GBA accesses immutable synthesis lookup tables in ROM; patch data is mutable.
s=s.replace('static uint16_t exp_table','static const uint16_t exp_table').replace('static int8_t pm_table','static const int8_t pm_table').replace('static uint8_t am_table','static const uint8_t am_table').replace('static uint8_t eg_step_tables','static const uint8_t eg_step_tables').replace('static uint32_t ml_table','static const uint32_t ml_table')
(P/'opll_gba.c').write_text(s)
h=(P/'vendor/emu2413/emu2413.h').read_text().replace('uint16_t *wave_table','const uint16_t *wave_table')
for name in ['inp_step','out_step','out_time']:h=h.replace('double '+name,'uint32_t '+name)
(P/'include/emu2413.h').write_text(h)
